            a[i]=a[i]-'0'+'x';
        }else if(a[i]>='d'&&a[i]<='z'){
            a[i]=a[i]-3;
        }else if(a[i]>='a'&&a[i]<='c'){
            a[i]=a[i]-'a'+'7';
        }
    }
    cout << a;
    return 0;
}
